const test=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'../manual-invite-campaign.js'),'utf8');
const accounts=[{id:'primary',username:'demo_sender',telegram_id:710001001,connection:'connected',enabled:0},{id:'canada_test',username:'canada_test',telegram_id:123456,connection:'connected',enabled:1}];
const target={id:-100555,title:'Дубай: новый чат',username:'demo_target',managed:true,can_invite:true};
function harness(seed){
 const handlers={},calls=[],timers=new Map(),timerDelays=[];let next=0;const memory=new Map(seed||[]),nodes={};let writes=0,html='';const el={get innerHTML(){return html;},set innerHTML(value){html=value;writes++;},querySelector:selector=>{if(selector==='.cc-error')return null;if(selector==='[aria-invalid="true"]')return Object.values(nodes).find(n=>n.attributes['aria-invalid']==='true')||null;return nodes[selector]??=({attributes:{},textContent:'',innerHTML:'',focused:false,setAttribute(k,v){this.attributes[k]=v;},focus(){this.focused=true;}});},querySelectorAll:()=>[]};
 const context={window:{},document:{querySelector:()=>el,addEventListener:(k,fn)=>{(handlers[k]??=[]).push(fn)}},sessionStorage:{getItem:k=>memory.get(k),setItem:(k,v)=>memory.set(k,v)},crypto:require('node:crypto').webcrypto,AbortSignal,Date,URLSearchParams,location:{search:''},console,setTimeout:(fn,delay)=>{timerDelays.push(delay);timers.set(++next,fn);return next;},clearTimeout:id=>timers.delete(id)};
 context.fetch=async(url,options)=>{let body=options.body?JSON.parse(options.body):undefined;calls.push({url,method:options.method,body});if(context.fetchOverride){const override=await context.fetchOverride(url,options);if(override!==undefined)return override;}let value;if(url==='/api/scanner/operations')value={accounts,jobs:[]};else if(url.includes('/destinations?'))value={account:'primary',telegram_id:710001001,username:'demo_sender',destinations:[target],invitation_requested:false};else if(url.endsWith('/preview')){if(!url.includes('/jobs/'))context.config=body;body=context.config;value={preview_id:'proof1',state:'checking',checked:0,total:body.users.length,config:body,account:body.account,telegram_id:body.telegram_id,target:{id:body.target_id,username:body.target_username},invitation_requested:false};}else if(url.endsWith('/previews/proof1')){const c=context.config;value={preview_id:'proof1',state:'ready',config:c,account:c.account,telegram_id:c.telegram_id,target,candidate_token:'x'.repeat(43),token_ttl_seconds:300,selected:c.users.map(username=>({username,member:false,checked_at:new Date().toISOString()})),account_attempts_today:0,remaining_attempts_today:25,invitation_requested:false};}else if(url.endsWith('/draft')){const c=body.config;value={job_id:991,state:'draft',config:c,account:c.account,telegram_id:c.telegram_id,target,counts:{added:0,total:c.users.length,attempts:0},items:[],account_attempts_today:0};context.job=value;}else if(url.endsWith('/quick-draft')){value=quickRecord(body.config);context.job=value;}else if(url.includes('/draft-requests/')){if(!context.job)return {ok:false,status:404,json:async()=>({detail:'not found'})};value=context.job;}else if(url.endsWith('/quick-start')){value={...context.job,state:'running',can_pause:true,can_resume:false};context.job=value;}else if(url.endsWith('/start')){value={...context.job,state:'running',can_pause:true,can_resume:false};context.job=value;}else if(url.endsWith('/pause')){value=context.pauseIntent?{...context.job,state:'running',pause_requested:true,can_pause:true,can_resume:false}:{...context.job,state:'paused',can_pause:false,can_resume:true};context.job=value;}else if(url.includes('/status?')){value=context.job;}else throw Error('Unexpected route '+url);return {ok:true,json:async()=>value};};
 vm.runInNewContext(source,context);const module=context.window.ManualInviteCampaign;
 async function flush(){for(let i=0;i<8;i++)await new Promise(resolve=>setImmediate(resolve));}
 async function event(kind,key,value){const t={dataset:{micField:key},value,checked:value,closest:()=>el};for(const f of handlers[kind]||[])f({target:t});await flush();}
 async function click(action){const b={dataset:{mic:action},closest:()=>el,disabled:false};for(const f of handlers.click||[])f({target:{closest:()=>b},preventDefault(){}});await flush();}
 async function tick(){const list=[...timers.values()];timers.clear();for(const fn of list)fn();await flush();}
 return {module,calls,el,event,click,tick,context,nodes,memory,handlers,timers,timerDelays,flush,writes:()=>writes};
}
function readyConfig(api){const d=api.initial();Object.assign(d,{account:'primary',telegram_id:710001001,target_id:target.id,users:'@valid_user\n@another_user',consent_note:'Согласие на вступление получено в заявках',consent_confirmed:true});return d;}
test('paused primary is connected, fresh draft has no Canada or group default',()=>{const x=harness(),api=x.module._test;assert.equal(api.connected(accounts[0]),true);assert.equal(api.initial().account,'');assert.equal(api.initial().target_id,null);const c=api.config(readyConfig(api),accounts,[target]);assert.equal(c.account,'primary');assert.equal(c.target_username,'demo_target');assert.equal(c.max_attempts,25);assert.equal(c.interval_seconds,60);assert.equal(c.success_goal,null);});
test('software limits, sender identity, group rights, duplicates and consent validate',()=>{const api=harness().module._test;for(const [key,value]of [['max_attempts',0],['max_attempts',1001],['account_day_attempt_cap',1.5],['interval_seconds',86401],['success_goal',3],['telegram_id',123456],['consent_confirmed',false],['users','@valid_user @valid_user']]){const d=readyConfig(api);d[key]=value;assert.throws(()=>api.config(d,accounts,[target]),key);}const d=readyConfig(api);Object.assign(d,{max_attempts:1000,account_day_attempt_cap:1000,interval_seconds:1,success_goal:2});assert.equal(api.config(d,accounts,[target]).success_goal,2);assert.throws(()=>api.config(d,accounts,[{...target,can_invite:false}]));});
test('editing any configuration invalidates proof, confirmation and old job',()=>{const api=harness().module._test,m=api.createModel();m.preview={candidate_token:'old'};m.confirmed=true;m.job={job_id:1};m.saveKey='old';m.edit('interval_seconds',1);assert.equal(m.preview,null);assert.equal(m.confirmed,false);assert.equal(m.job,null);assert.equal(m.saveKey,'');assert.equal(m.revision,1);});
test('mount does only cached account GET, does not select Canada or start invitations',async()=>{const x=harness();await x.module.mount();assert.equal(x.calls.length,1);assert.equal(x.calls[0].method,'GET');assert.ok(!x.el.innerHTML.includes('value="canada_test" selected'));assert.match(x.el.innerHTML,/@demo_sender/);assert.match(x.el.innerHTML,/общая очередь на паузе/);assert.ok(!x.el.innerHTML.includes('цели 100'));});
test('explicit paused sender, new target, async preview and draft never call start or resume queue',async()=>{const x=harness();await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','@valid_user\n@another_user');await x.event('input','consent_note','Все участники согласились в заявках');await x.event('change','consent_confirmed',true);await x.event('input','max_attempts','2');await x.event('input','account_day_attempt_cap','25');await x.event('input','interval_seconds','1');await x.event('input','success_goal','2');await x.click('preview');assert.match(x.el.innerHTML,/Проверяем участников: 0 из 2/);await x.tick();assert.match(x.el.innerHTML,/Список проверен/);await x.click('draft');assert.match(x.el.innerHTML,/Черновик сохранён/);const post=x.calls.filter(c=>c.method==='POST');assert.deepEqual(post.map(c=>c.url.split('/').at(-1)),['preview','draft']);assert.equal(post[0].body.account,'primary');assert.equal(post[0].body.target_id,target.id);assert.equal(post[0].body.interval_seconds,1);assert.equal(post[0].body.success_goal,2);assert.equal(post[1].body.config.consent_confirmed,true);assert.ok(!x.calls.some(c=>/start|resume-outbound/.test(c.url)));});
test('editing after ready preview removes saved proof and disables old draft action',async()=>{const x=harness();await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','@valid_user');await x.event('input','consent_note','Участник согласился в заявке');await x.event('change','consent_confirmed',true);await x.click('preview');await x.tick();await x.event('input','interval_seconds','2');await x.click('draft');assert.ok(!x.calls.some(c=>c.url.endsWith('/draft')));assert.match(x.el.innerHTML,/Срок проверки истёк/);});

test('start needs explicit confirmation; pause and fresh resume affect only the saved job',async()=>{const x=harness();await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','@valid_user');await x.event('input','consent_note','Участник согласился в заявке');await x.event('change','consent_confirmed',true);await x.click('preview');await x.tick();await x.click('draft');await x.click('start');assert.ok(!x.calls.some(c=>c.url.endsWith('/start')));await x.event('change','confirmed',true);await x.click('start');assert.match(x.el.innerHTML,/Выполняется/);await x.click('pause');assert.match(x.el.innerHTML,/На паузе/);await x.click('recheck');await x.tick();await x.event('change','confirmed',true);await x.click('start');const starts=x.calls.filter(c=>c.url.endsWith('/start'));assert.equal(starts.length,2);assert.equal(starts[0].body.job_id,991);assert.equal(starts[1].body.job_id,991);assert.notEqual(starts[0].body.request_key,starts[1].body.request_key);assert.ok(!x.calls.some(c=>c.url.includes('resume-outbound')));});

test('pause intent stays running, disables pause and polls until backend confirms paused',async()=>{const x=harness();await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','@valid_user');await x.event('input','consent_note','Участник согласился в заявке');await x.event('change','consent_confirmed',true);await x.click('preview');await x.tick();await x.click('draft');await x.event('change','confirmed',true);await x.click('start');x.context.pauseIntent=true;await x.click('pause');assert.match(x.el.innerHTML,/Останавливаем после текущего запроса/);assert.match(x.el.innerHTML,/data-mic="pause" disabled/);assert.match(x.el.innerHTML,/3\. Выполняется/);assert.ok(!x.el.innerHTML.includes('3. На паузе'));x.context.job={...x.context.job,state:'paused',pause_requested:false,can_pause:false,can_resume:true};await x.tick();assert.match(x.el.innerHTML,/3\. На паузе/);assert.ok(!x.el.innerHTML.includes('data-mic="pause"'));});

test('formatted participant lines extract only explicit handles and accept plain handles/profile URLs',()=>{const api=harness().module._test;const parsed=api.parseUsers('Иван Петров — @Some_User\nplain_handle\nhttps://t.me/profile_user\nМария — t.me/another_user');assert.deepEqual(Array.from(parsed.users),['some_user','plain_handle','profile_user','another_user']);assert.equal(parsed.issues.length,0);const d=readyConfig(api);d.users='Иван — @valid_user\nhttps://t.me/another_user';assert.deepEqual(Array.from(api.config(d,accounts,[target]).users),['valid_user','another_user']);});
 test('invalid and duplicate participants identify exact line without stripping names into handles',()=>{const api=harness().module._test;const p=api.parseUsers('Имя без адреса\nИван — @valid_user\n@VALID_USER\n@two_users @other_user\nhttps://t.me/+secret');assert.equal(p.users.length,1);assert.match(p.issues[0],/Строка 1/);assert.match(p.issues[1],/Строка 3.*повторяет строку 2/);assert.match(p.issues[2],/Строка 4/);assert.match(p.issues[3],/Строка 5/);const d=readyConfig(api);d.users='Имя без адреса';assert.match(api.fieldErrors(d,accounts,[target]).users,/Строка 1/);});
 test('idle save stays clickable; validation identifies required fields and prevents invalid API writes',async()=>{const x=harness();await x.module.mount();assert.match(x.el.innerHTML,/data-mic="quick-draft">Сохранить кампанию/);await x.click('quick-draft');assert.ok(!x.calls.some(c=>c.method==='POST'));assert.match(x.el.innerHTML,/Чтобы сохранить кампанию, исправьте поля/);assert.match(x.el.innerHTML,/id="mic-account" aria-invalid="true" aria-describedby="mic-account-error"/);assert.match(x.el.innerHTML,/id="mic-users-error">Укажите от 1 до 1000/);assert.match(x.el.innerHTML,/от 8 до 500 символов/);});
 test('live field hints update without replacing form or losing raw formatted text in session',async()=>{const x=harness();await x.module.mount();const before=x.writes();const raw='Иван — @valid_user\nИмя без адреса';await x.event('input','users',raw);assert.equal(x.writes(),before);assert.equal(x.nodes['[data-mic-field="users"]'].attributes['aria-invalid'],'true');assert.match(x.nodes['#mic-users-error'].textContent,/Строка 2/);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).draft.users,raw);await x.event('input','users','Иван — @valid_user');assert.equal(x.nodes['[data-mic-field="users"]'].attributes['aria-invalid'],'false');assert.equal(x.nodes['#mic-users-error'].textContent,'');await x.event('input','interval_seconds','0');assert.match(x.nodes['#mic-interval_seconds-error'].textContent,/целое число от 1 до 86400/);assert.equal(x.writes(),before);});
 test('formatted list is sent as handles only; self-contained full-width/red-state CSS exists',async()=>{const x=harness();await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','Иван — @valid_user\nhttps://t.me/another_user');await x.event('input','consent_note','Все участники согласились в заявках');await x.event('change','consent_confirmed',true);await x.click('preview');const p=x.calls.find(c=>c.url.endsWith('/preview'));assert.deepEqual(p.body.users,['valid_user','another_user']);assert.match(x.el.innerHTML,/#manual-invite-campaign \.cc-field\{display:flex;flex-direction:column/);assert.match(x.el.innerHTML,/#manual-invite-campaign \[aria-invalid=true\]\{border:2px solid/);assert.match(x.el.innerHTML,/width:100%;min-width:0;border:1px solid/);assert.match(x.el.innerHTML,/@media\(max-width:600px\)/);});

test('r2 reload preserves r1 session raw formatted list and every chosen setting',async()=>{const x=harness();await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));const raw='Иван Петров — @valid_user\nМария — @another_user';await x.event('input','users',raw);await x.event('input','interval_seconds','37');await x.event('input','max_attempts','80');await x.event('input','consent_note','Подтверждения получены в заявках');await x.event('change','consent_confirmed',true);const saved=x.memory.get('manual-invite-campaign-v1');x.module.unmount();const next=harness(x.memory);await next.module.mount();const restored=JSON.parse(next.memory.get('manual-invite-campaign-v1'));assert.equal(restored.draft.users,raw);assert.equal(restored.draft.max_attempts,80);assert.equal(restored.draft.interval_seconds,37);assert.equal(restored.draft.consent_note,'Подтверждения получены в заявках');assert.equal(restored.draft.target_id,target.id);assert.equal(restored.draft.account,'primary');assert.equal(restored.draft.consent_confirmed,true);assert.ok(next.el.innerHTML.includes(raw));assert.match(next.el.innerHTML,/Распознано 2 профилей/);assert.equal(next.calls.filter(c=>c.method==='POST').length,0);assert.equal(JSON.parse(saved).draft.users,restored.draft.users);});

test('anchored parser rejects residual text, email-like strings, foreign domains and malformed list lines',()=>{const api=harness().module._test;for(const line of ['@valid_user, broken!','person@valid_user','https://not-t.me/valid_user','https://example.com/t.me/valid_user','@valid_user trailing','Имя — @valid_user, broken!','t.me/valid_user/extra','@valid_user @other_user']){const p=api.parseUsers(line);assert.equal(p.users.length,0,line);assert.match(p.issues[0],/Строка 1/,line);}for(const line of ['Имя—@valid_user','Имя – @valid_user','Имя - @valid_user','Имя — https://t.me/valid_user','https://t.me/valid_user/']){assert.equal(api.parseUsers(line).users[0],'valid_user',line);}});
 test('validation navigation uses local focus buttons, never application hash routes',async()=>{const x=harness();await x.module.mount();await x.click('preview');assert.match(x.el.innerHTML,/data-mic-focus="users"/);assert.ok(!x.el.innerHTML.includes('href="#mic-'));});

test('error summary click focuses local field and prevents route-changing default action',async()=>{const x=harness();await x.module.mount();await x.click('preview');let prevented=false,stopped=false;const focusButton={dataset:{micFocus:'users'},closest:()=>x.el};for(const listener of x.handlers.click||[])listener({target:{closest:selector=>selector==='[data-mic-focus]'?focusButton:null},preventDefault(){prevented=true;},stopPropagation(){stopped=true;}});assert.equal(prevented,true);assert.equal(stopped,true);assert.equal(x.nodes['[data-mic-field="users"]'].focused,true);assert.equal(x.calls.length,1);});

async function newPreview(x){await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','Имя — @valid_user');await x.event('input','consent_note','Участник согласился в заявке');await x.event('change','consent_confirmed',true);await x.click('preview');}
const response=value=>({ok:true,status:200,json:async()=>value});
function cachedProgress(c,state='ready'){return {preview_id:'proof1',created_at:Date.now()/1000,state,checked:state==='ready'?1:0,total:1,config:c,account:c.account,telegram_id:c.telegram_id,target,invitation_requested:false,...(state==='ready'?{candidate_token:'x'.repeat(43),token_ttl_seconds:300,selected:[{username:'valid_user',member:false,checked_at:new Date().toISOString()}],account_attempts_today:0,remaining_attempts_today:25}:{})};}
test('transient cached GET timeout retries and recovers without POST replay or persisting bearer',async()=>{const x=harness();await newPreview(x);let failures=1;x.context.fetchOverride=async url=>{if(url.includes('/previews/')&&failures-->0)throw Error('timeout');};await x.tick();assert.match(x.el.innerHTML,/Связь с сервером прервалась/);assert.equal(x.timerDelays.at(-1),2000);await x.tick();assert.match(x.el.innerHTML,/Список проверен/);assert.ok(!x.el.innerHTML.includes('Связь с сервером прервалась'));assert.equal(x.calls.filter(c=>c.method==='POST').length,1);assert.equal(x.calls.filter(c=>c.url.includes('/previews/')).length,2);assert.ok(!x.memory.get('manual-invite-campaign-v1').includes('candidate_token'));assert.ok(!x.memory.get('manual-invite-campaign-v1').includes('x'.repeat(43)));});
test('GET retry backoff is bounded and manual update reads same preview ID only',async()=>{const x=harness();await newPreview(x);x.context.fetchOverride=async url=>{if(url.includes('/previews/'))throw Error('timeout');};for(let i=0;i<5;i++)await x.tick();assert.deepEqual(x.timerDelays.slice(-4),[2000,5000,10000,15000]);assert.equal(x.timers.size,0);assert.match(x.el.innerHTML,/Автоматическое обновление остановлено/);assert.match(x.el.innerHTML,/data-mic="refresh-preview"/);assert.equal(x.calls.filter(c=>c.url.includes('/previews/')).length,5);x.context.fetchOverride=null;await x.click('refresh-preview');assert.match(x.el.innerHTML,/Список проверен/);assert.equal(x.calls.filter(c=>c.url.endsWith('/previews/proof1')).length,6);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);});
test('reload reattaches cached preview GET, preserves raw input and skips redundant group Telegram read',async()=>{const first=harness();await newPreview(first);const raw=JSON.parse(first.memory.get('manual-invite-campaign-v1')).draft.users;first.module.unmount();const x=harness(first.memory),cache=JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef;x.context.config=cache.config;x.context.fetchOverride=async url=>url.includes('/previews/')?response(cachedProgress(cache.config)):undefined;await x.module.mount();assert.match(x.el.innerHTML,/Список проверен/);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);assert.equal(x.calls.filter(c=>c.url.includes('/previews/proof1')).length,1);assert.equal(x.calls.filter(c=>c.url.includes('/destinations')).length,0);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).draft.users,raw);assert.ok(!x.memory.get('manual-invite-campaign-v1').includes('candidate_token'));});
test('editing config clears persisted attachment and obsolete poll without network replay',async()=>{const x=harness();await newPreview(x);await x.event('input','interval_seconds','2');await x.tick();assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef,null);assert.equal(x.calls.filter(c=>c.url.includes('/previews/')).length,0);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);});
test('restore rejects stale config or revision bindings instead of attaching cached GET',async()=>{for(const change of ['config','revision']){const first=harness();await newPreview(first);first.module.unmount();const cache=JSON.parse(first.memory.get('manual-invite-campaign-v1'));if(change==='config')cache.draft.interval_seconds=2;else cache.revision++;first.memory.set('manual-invite-campaign-v1',JSON.stringify(cache));const x=harness(first.memory);await x.module.mount();assert.equal(x.calls.filter(c=>c.url.includes('/previews/')).length,0,change);assert.equal(x.calls.filter(c=>c.method==='POST').length,0,change);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef,null,change);}});
test('not found/failed cached preview becomes terminal and never starts a new POST automatically',async()=>{for(const kind of ['notfound','failed']){const x=harness();await newPreview(x);x.context.fetchOverride=async url=>{if(!url.includes('/previews/'))return;if(kind==='notfound')return {ok:false,status:404,json:async()=>({detail:'missing'})};return response({...cachedProgress(x.context.config,'checking'),state:'failed',error:'Проверка остановлена сервером.'});};await x.tick();assert.match(x.el.innerHTML,/Начать новую проверку/);assert.equal(x.timers.size,0);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef,null);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);}});
test('unmounted lifecycle ignores delayed cached response and schedules no further work',async()=>{const x=harness();await newPreview(x);let resolve;x.context.fetchOverride=async url=>url.includes('/previews/')?new Promise(r=>resolve=r):undefined;const pending=x.tick();await x.flush();x.module.unmount();resolve(response(cachedProgress(x.context.config)));await pending;assert.equal(x.timers.size,0);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);});

const migrationId='B'.repeat(32);
test('explicit preview URL migrates matching r2 input through cached GET without normalizing raw text',async()=>{const first=harness();await newPreview(first);const old=JSON.parse(first.memory.get('manual-invite-campaign-v1')),c=old.previewRef.config,raw=old.draft.users;delete old.previewRef;delete old.revision;first.memory.set('manual-invite-campaign-v1',JSON.stringify(old));first.module.unmount();const x=harness(first.memory);x.context.location.search='?invite_preview='+migrationId;x.context.fetchOverride=async url=>url.includes('/previews/')?response({...cachedProgress(c,'checking'),preview_id:migrationId}):undefined;await x.module.mount();const after=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(after.draft.users,raw);assert.equal(after.previewRef.id,migrationId);assert.match(x.el.innerHTML,/Проверяем участников: 0 из 1/);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);assert.equal(x.calls.filter(c=>c.url.includes('/destinations')).length,0);assert.equal(x.calls.filter(c=>c.url.endsWith('/previews/'+migrationId)).length,1);});
test('explicit preview URL with mismatched existing draft never overwrites input or posts',async()=>{const first=harness();await newPreview(first);const old=JSON.parse(first.memory.get('manual-invite-campaign-v1')),c={...old.previewRef.config,users:['another_user']};delete old.previewRef;first.memory.set('manual-invite-campaign-v1',JSON.stringify(old));first.module.unmount();const x=harness(first.memory);x.context.location.search='?invite_preview='+migrationId;x.context.fetchOverride=async url=>url.includes('/previews/')?response({...cachedProgress(c,'checking'),preview_id:migrationId}):undefined;await x.module.mount();assert.match(x.el.innerHTML,/относится к другим настройкам/);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).draft.users,old.draft.users);assert.ok(x.el.innerHTML.includes(old.draft.users));assert.equal(x.calls.filter(c=>c.method==='POST').length,0);assert.equal(x.calls.filter(c=>c.url.includes('/destinations')).length,0);});
test('explicit preview URL in empty tab hydrates only server-bound draft and does not read groups',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.location.search='?invite_preview='+migrationId;x.context.fetchOverride=async url=>url.includes('/previews/')?response({...cachedProgress(c,'checking'),preview_id:migrationId}):undefined;await x.module.mount();const saved=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(saved.draft.account,'primary');assert.equal(saved.draft.target_id,target.id);assert.equal(saved.previewRef.id,migrationId);assert.equal(x.calls.filter(c=>c.method==='POST'||c.url.includes('/destinations')).length,0);});
test('old cached ready proof stays visibly expired through refresh and never enables save',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.location.search='?invite_preview='+migrationId;let fresh=false;x.context.fetchOverride=async url=>url.includes('/previews/')?response({...cachedProgress(c),preview_id:migrationId,created_at:Date.now()/1000-600,selected:[{username:'valid_user',member:false,checked_at:new Date(Date.now()-(fresh?0:600000)).toISOString()}]}):undefined;await x.module.mount();assert.match(x.el.innerHTML,/Срок проверки истёк/);assert.match(x.el.innerHTML,/data-mic="draft" disabled/);const before=JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef.expiresAt;fresh=true;await x.click('refresh-preview');assert.match(x.el.innerHTML,/Срок проверки истёк/);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef.expiresAt,before);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});
test('checking deadline survives reload, expires at original creation and does no new cached GET or POST',async()=>{const first=harness();await newPreview(first);first.module.unmount();const saved=JSON.parse(first.memory.get('manual-invite-campaign-v1'));saved.previewRef.createdAt=Date.now()-4000000;first.memory.set('manual-invite-campaign-v1',JSON.stringify(saved));const x=harness(first.memory);await x.module.mount();assert.match(x.el.innerHTML,/Срок ожидания проверки истёк/);assert.equal(x.calls.filter(c=>c.url.includes('/previews/')||c.url.includes('/destinations')||c.method==='POST').length,0);assert.equal(x.timers.size,0);});
test('cached GET cannot attach another preview ID',async()=>{const x=harness();await newPreview(x);x.context.fetchOverride=async url=>url.includes('/previews/')?response({...cachedProgress(x.context.config),preview_id:'wrong_id'}):undefined;await x.tick();assert.match(x.el.innerHTML,/Сервер вернул другую проверку/);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef,null);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);});

test('ordinary preview click during checking or recovery reads existing ID without duplicate POST',async()=>{const x=harness();await newPreview(x);x.context.fetchOverride=async url=>url.includes('/previews/')?response(cachedProgress(x.context.config,'checking')):undefined;await x.click('preview');assert.equal(x.calls.filter(c=>c.method==='POST').length,1);assert.equal(x.calls.filter(c=>c.url.endsWith('/previews/proof1')).length,1);x.context.fetchOverride=async url=>{if(url.includes('/previews/'))throw Error('timeout');};await x.tick();assert.match(x.el.innerHTML,/Связь с сервером прервалась/);await x.click('preview');assert.equal(x.calls.filter(c=>c.method==='POST').length,1);assert.ok(x.calls.filter(c=>c.url.endsWith('/previews/proof1')).length>=3);});

test('explicit URL initial GET timeout also retries only cached reads and exposes manual refresh',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.location.search='?invite_preview='+migrationId;let fail=true;x.context.fetchOverride=async url=>{if(!url.includes('/previews/'))return;if(fail)throw Error('timeout');return response({...cachedProgress(c,'checking'),preview_id:migrationId});};await x.module.mount();assert.match(x.el.innerHTML,/Связь с сервером прервалась/);assert.match(x.el.innerHTML,/data-mic="refresh-preview"/);fail=false;await x.click('refresh-preview');assert.match(x.el.innerHTML,/Проверяем участников/);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef.id,migrationId);assert.equal(x.calls.filter(c=>c.method==='POST'||c.url.includes('/destinations')).length,0);});

function trackHistory(x){const writes=[];x.context.location.pathname='/panel/';x.context.location.hash='#invite-settings';x.context.window.history={replaceState(state,title,url){writes.push(url);const parsed=new URL(url,'https://panel.example');x.context.location.search=parsed.search;x.context.location.hash=parsed.hash;}};return writes;}
test('bound URL attach consumes only preview query and preserves other parameters/hash without hash navigation',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]),writes=trackHistory(x);x.context.location.search='?view=client&invite_preview='+migrationId+'&language=ru';x.context.fetchOverride=async url=>url.includes('/previews/')?response({...cachedProgress(c,'checking'),preview_id:migrationId}):undefined;await x.module.mount();assert.deepEqual(writes,['/panel/?view=client&language=ru#invite-settings']);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});
test('explicit new preview ACK consumes stale URL after missing old preview; click alone before ACK does not',async()=>{const first=harness();await newPreview(first);const saved=JSON.parse(first.memory.get('manual-invite-campaign-v1'));delete saved.previewRef;first.memory.set('manual-invite-campaign-v1',JSON.stringify(saved));first.module.unmount();const x=harness(first.memory),writes=trackHistory(x);x.context.location.search='?invite_preview='+migrationId+'&view=client';x.context.fetchOverride=async url=>url.endsWith('/previews/'+migrationId)?{ok:false,status:404,json:async()=>({detail:'missing'})}:undefined;await x.module.mount();assert.equal(writes.length,0);await x.click('groups');await x.click('preview');assert.equal(x.calls.filter(c=>c.method==='POST').length,1);assert.deepEqual(writes,['/panel/?view=client#invite-settings']);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).previewRef.id,'proof1');});

test('editing after URL attach timeout clears pending URL/retry and allows a distinct explicit preview POST',async()=>{const first=harness();await newPreview(first);const old=JSON.parse(first.memory.get('manual-invite-campaign-v1'));delete old.previewRef;first.memory.set('manual-invite-campaign-v1',JSON.stringify(old));first.module.unmount();const x=harness(first.memory),writes=trackHistory(x);x.context.location.search='?invite_preview='+migrationId+'&view=client';x.context.fetchOverride=async url=>{if(url.endsWith('/previews/'+migrationId))throw Error('timeout');};await x.module.mount();assert.match(x.el.innerHTML,/Связь с сервером прервалась/);await x.event('input','interval_seconds','2');assert.deepEqual(writes,['/panel/?view=client#invite-settings']);assert.equal(x.timers.size,0);await x.tick();await x.click('groups');await x.click('preview');assert.equal(x.calls.filter(c=>c.url.endsWith('/previews/'+migrationId)).length,1);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);assert.equal(x.calls.find(c=>c.method==='POST').body.interval_seconds,2);});
test('late URL attach response after unmount does not hydrate draft, persist token or schedule retry',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.location.search='?invite_preview='+migrationId;let resolve;x.context.fetchOverride=async url=>url.includes('/previews/')?new Promise(r=>resolve=r):undefined;const mounting=x.module.mount();await x.flush();x.module.unmount();resolve(response({...cachedProgress(c),preview_id:migrationId}));await mounting;assert.equal(x.memory.has('manual-invite-campaign-v1'),false);assert.equal(x.timers.size,0);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});

function quickRecord(c){return {job_id:992,resolution:'on_dispatch',config_digest:'a'.repeat(64),state:'draft',config:c,account:c.account,telegram_id:c.telegram_id,target,counts:{added:0,total:c.users.length,attempts:0,pending:c.users.length},items:c.users.map((user_name,i)=>({id:i+1,user_id:null,user_name,state:'pending'})),account_attempts_today:0,can_pause:false,can_resume:false,invitation_requested:false};}
async function fillQuick(x){await x.module.mount();await x.event('change','account','primary');await x.event('change','target_id',String(target.id));await x.event('input','users','Иван — @valid_user\nМария — @another_user');await x.event('input','consent_note','Оба участника подтвердили вступление в заявках');await x.event('change','consent_confirmed',true);await x.event('input','max_attempts','20');await x.event('input','account_day_attempt_cap','20');await x.event('input','interval_seconds','60');}
test('normal new flow saves unresolved cohort with no recipient preview and separate explicit start',async()=>{const x=harness();await fillQuick(x);assert.match(x.el.innerHTML,/data-mic="quick-draft">Сохранить кампанию/);assert.ok(!x.el.innerHTML.includes('data-mic="preview"'));await x.click('quick-draft');assert.match(x.el.innerHTML,/Кампания сохранена/);assert.match(x.el.innerHTML,/data-mic="start" disabled/);assert.ok(!x.el.innerHTML.includes('data-mic="recheck"'));assert.match(x.el.innerHTML,/@valid_user, @another_user/);assert.match(x.el.innerHTML,/Перед каждой попыткой проверяются только текущий профиль/);assert.deepEqual(x.calls.filter(c=>c.method==='POST').map(c=>c.url.split('/').at(-1)),['quick-draft']);const save=x.calls.find(c=>c.url.endsWith('/quick-draft'));assert.equal(save.body.config.account,'primary');assert.equal(save.body.config.max_attempts,20);assert.equal(save.body.config.account_day_attempt_cap,20);assert.ok(!('candidate_token' in save.body));assert.ok(x.context.job.items.every(i=>i.user_id===null));await x.click('start');assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);await x.event('change','confirmed',true);await x.click('start');const start=x.calls.find(c=>c.url.endsWith('/quick-start'));assert.equal(start.body.job_id,992);assert.equal(start.body.config_digest,'a'.repeat(64));assert.equal(start.body.confirmed,true);assert.ok(!('candidate_token' in start.body));assert.equal(x.calls.filter(c=>/\/preview$|\/previews\//.test(c.url)).length,0);});
test('lost quick save response recovers through cached request lookup, never automatic POST retry',async()=>{const x=harness();await fillQuick(x);x.context.fetchOverride=async(url,options)=>{if(url.endsWith('/quick-draft')){x.context.job=quickRecord(JSON.parse(options.body).config);throw Error('lost response');}};await x.click('quick-draft');assert.match(x.el.innerHTML,/Проверить сохранение кампании/);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-draft')).length,1);await x.click('recover-draft');assert.match(x.el.innerHTML,/Кампания сохранена/);assert.equal(x.calls.filter(c=>c.url.includes('/draft-requests/')).length,1);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);});
test('reload of uncertain quick save performs cached GET lookup only and preserves raw draft',async()=>{const first=harness();await fillQuick(first);first.context.fetchOverride=async(url,options)=>{if(url.endsWith('/quick-draft')){first.context.job=quickRecord(JSON.parse(options.body).config);throw Error('lost response');}};await first.click('quick-draft');const before=JSON.parse(first.memory.get('manual-invite-campaign-v1'));first.module.unmount();const x=harness(first.memory);x.context.job=first.context.job;await x.module.mount();assert.equal(x.calls.filter(c=>c.method==='POST').length,0);assert.equal(x.calls.filter(c=>c.url.includes('/destinations')).length,0);assert.equal(x.calls.filter(c=>c.url.includes('/draft-requests/')).length,1);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).draft.users,before.draft.users);assert.match(x.el.innerHTML,/Кампания сохранена/);});
test('confirmed missing quick save requires explicit same-key retry after cached 404',async()=>{const x=harness();await fillQuick(x);let first=true;x.context.fetchOverride=async url=>{if(url.endsWith('/quick-draft')&&first){first=false;throw Error('timeout before save');}};await x.click('quick-draft');const key=x.calls.find(c=>c.url.endsWith('/quick-draft')).body.request_key;await x.click('recover-draft');assert.match(x.el.innerHTML,/Повторить сохранение кампании/);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-draft')).length,1);await x.click('quick-draft');const posts=x.calls.filter(c=>c.url.endsWith('/quick-draft'));assert.equal(posts.length,2);assert.equal(posts[1].body.request_key,key);assert.equal(posts[0].body.config.users.join(','),posts[1].body.config.users.join(','));assert.equal(x.calls.filter(c=>c.url.includes('/quick-start')).length,0);});
test('lost quick start response uses known-job status recovery without automatic start replay',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');await x.event('change','confirmed',true);x.context.fetchOverride=async url=>{if(url.endsWith('/quick-start')){x.context.job={...x.context.job,state:'running',can_pause:true};throw Error('lost start response');}};await x.click('start');await x.click('status');assert.match(x.el.innerHTML,/2\. Выполняется/);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,1);assert.equal(x.calls.filter(c=>c.url.includes('/status?')).length,2);});
test('known quick job reload preserves formatted raw names, authoritative limits and no proof prerequisite',async()=>{const first=harness();await fillQuick(first);await first.click('quick-draft');const before=JSON.parse(first.memory.get('manual-invite-campaign-v1'));first.module.unmount();const x=harness(first.memory);x.context.job=first.context.job;await x.module.mount();const after=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(after.draft.users,before.draft.users);assert.equal(after.draft.max_attempts,20);assert.match(x.el.innerHTML,/Запустить кампанию/);assert.ok(!x.el.innerHTML.includes('data-mic="recheck"'));assert.equal(x.calls.filter(c=>c.method==='POST'||c.url.includes('/previews/')||c.url.includes('/destinations')).length,0);});
test('quick save validates missing fields inline before any API write',async()=>{const x=harness();await x.module.mount();await x.click('quick-draft');assert.equal(x.calls.filter(c=>c.method==='POST').length,0);assert.match(x.el.innerHTML,/Чтобы сохранить кампанию, исправьте поля/);assert.match(x.el.innerHTML,/id="mic-account" aria-invalid="true"/);});
test('quick status refuses changed authoritative digest before another start',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');x.context.job={...x.context.job,config_digest:'bad',counts:{total:2,attempts:1,added:0,restricted:1,pending:1},items:[{user_name:'valid_user',state:'restricted'},{user_name:'another_user',state:'pending'}],account_attempts_today:3};await x.click('status');assert.match(x.el.innerHTML,/Сервер вернул другую кампанию/);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);});

test('runtime counters distinguish verified additions, attempts, privacy outcomes and remaining daily budget',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');x.context.job={...x.context.job,state:'stopped',can_resume:true,counts:{total:2,attempts:1,added:0,restricted:1,pending:1},items:[{user_name:'valid_user',state:'restricted'},{user_name:'another_user',state:'pending'}],account_attempts_today:3};await x.click('status');assert.match(x.el.innerHTML,/Подтверждённых новых<\/dt><dd>0/);assert.match(x.el.innerHTML,/Попытки кампании<\/dt><dd>1 из 20/);assert.match(x.el.innerHTML,/Осталось дневных попыток<\/dt><dd>17/);assert.match(x.el.innerHTML,/Отказы и приватность Telegram<\/dt><dd>1/);assert.match(x.el.innerHTML,/@valid_user · Отказ Telegram/);assert.match(x.el.innerHTML,/Продолжить кампанию/);assert.ok(!x.el.innerHTML.includes('data-mic="recheck"'));});
test('wrong quick response marker is rejected and cannot enable start',async()=>{const x=harness();await fillQuick(x);x.context.fetchOverride=async(url,options)=>url.endsWith('/quick-draft')?response({...quickRecord(JSON.parse(options.body).config),resolution:'other'}):undefined;await x.click('quick-draft');assert.match(x.el.innerHTML,/Сервер не подтвердил сохранённую кампанию/);assert.ok(!x.el.innerHTML.includes('data-mic="start"'));assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);});
test('existing unsaved 100-person raw draft survives quick release reload without account fallback or recipient scan',async()=>{const first=harness();await fillQuick(first);const raw=Array.from({length:100},(_,i)=>'Участник '+(i+1)+' — @person_'+String(i).padStart(3,'0')).join('\n');await first.event('input','users',raw);await first.event('input','max_attempts','100');await first.event('input','account_day_attempt_cap','100');first.module.unmount();const x=harness(first.memory);await x.module.mount();const saved=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(saved.draft.users,raw);assert.equal(saved.draft.account,'primary');assert.equal(saved.draft.target_id,target.id);assert.equal(saved.draft.max_attempts,100);assert.equal(saved.draft.account_day_attempt_cap,100);assert.match(x.el.innerHTML,/Распознано 100 профилей/);assert.equal(x.calls.filter(c=>c.method==='POST'||c.url.includes('/preview')).length,0);assert.match(x.el.innerHTML,/Сохранить кампанию/);});

test('explicit job URL has priority and displays a running campaign through cached status GET only',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.job={...quickRecord(c),state:'running',can_pause:true,counts:{total:2,attempts:1,added:1,pending:1},account_attempts_today:1};x.context.location.search='?invite_job=992&invite_preview='+migrationId;await x.module.mount();assert.match(x.el.innerHTML,/2\. Выполняется · №992/);assert.match(x.el.innerHTML,/Подтверждённых новых<\/dt><dd>1/);assert.match(x.el.innerHTML,/@valid_user, @another_user/);assert.equal(x.calls.filter(c=>c.url.includes('/status?job_id=992')).length,1);assert.equal(x.calls.filter(c=>c.method==='POST'||c.url.includes('/preview')||c.url.includes('/destinations')).length,0);assert.equal(x.context.location.search,'?invite_job=992&invite_preview='+migrationId);});
test('viewing another job preserves unsaved raw input backup and New campaign restores it without writes',async()=>{const first=harness();await fillQuick(first);const before=JSON.parse(first.memory.get('manual-invite-campaign-v1'));first.module.unmount();const x=harness(first.memory),writes=trackHistory(x),c={...x.module._test.config(readyConfig(x.module._test),accounts,[target]),users:['viewed_user']};x.context.job={...quickRecord(c),state:'completed'};x.context.location.search='?invite_job=992&view=client';await x.module.mount();const viewing=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(viewing.viewBackup.draft.users,before.draft.users);assert.match(x.el.innerHTML,/@viewed_user/);await x.click('new');const after=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(after.draft.users,before.draft.users);assert.equal(after.draft.max_attempts,before.draft.max_attempts);assert.equal(after.draft.account,before.draft.account);assert.equal(after.draft.target_id,before.draft.target_id);assert.equal(after.viewBackup,null);assert.equal(after.jobId,null);assert.deepEqual(writes,['/panel/?view=client#invite-settings']);assert.match(x.el.innerHTML,/Ваш несохранённый список восстановлен/);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});

test('known404 enables explicit edit preserving raw; changed config saves only on new click with fresh key',async()=>{const x=harness();await fillQuick(x);const raw=JSON.parse(x.memory.get('manual-invite-campaign-v1')).draft.users;let first=true;x.context.fetchOverride=async url=>{if(url.endsWith('/quick-draft')&&first){first=false;throw Error('timeout');}};await x.click('quick-draft');const firstKey=x.calls.find(c=>c.url.endsWith('/quick-draft')).body.request_key;assert.ok(!x.el.innerHTML.includes('data-mic="edit-missing-draft"'));await x.click('recover-draft');assert.match(x.el.innerHTML,/data-mic="edit-missing-draft">Изменить настройки/);await x.click('edit-missing-draft');const unlocked=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(unlocked.draft.users,raw);assert.equal(unlocked.pendingWrite,'');assert.equal(unlocked.pendingConfig,null);assert.equal(unlocked.saveKey,'');assert.ok(!x.el.innerHTML.includes('<fieldset disabled>'));assert.equal(x.calls.filter(c=>c.method==='POST').length,1);await x.event('input','interval_seconds','31');await x.click('quick-draft');const posts=x.calls.filter(c=>c.url.endsWith('/quick-draft'));assert.equal(posts.length,2);assert.notEqual(posts[1].body.request_key,firstKey);assert.equal(posts[1].body.config.interval_seconds,31);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);});
test('unknown quick save outcome cannot be unlocked before cached lookup reports404',async()=>{const x=harness();await fillQuick(x);x.context.fetchOverride=async url=>{if(url.endsWith('/quick-draft'))throw Error('timeout');};await x.click('quick-draft');const before=JSON.parse(x.memory.get('manual-invite-campaign-v1'));await x.click('edit-missing-draft');const after=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(after.pendingWrite,'quick-draft');assert.equal(after.saveKey,before.saveKey);assert.deepEqual(after.pendingConfig,before.pendingConfig);assert.match(x.el.innerHTML,/<fieldset disabled>/);assert.equal(x.calls.filter(c=>c.method==='POST').length,1);});

test('lost start response cannot discard job through New campaign before cached status success',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');await x.event('change','confirmed',true);x.context.fetchOverride=async url=>{if(url.endsWith('/quick-start'))throw Error('lost ACK');};await x.click('start');const before=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(before.pendingWrite,'quick-start');assert.match(x.el.innerHTML,/data-mic="new" disabled/);await x.click('new');const blocked=JSON.parse(x.memory.get('manual-invite-campaign-v1'));assert.equal(blocked.jobId,992);assert.equal(blocked.pendingWrite,'quick-start');assert.equal(blocked.startKey,before.startKey);assert.match(x.el.innerHTML,/Сначала обновите состояние/);await x.click('status');assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).pendingWrite,'');await x.click('new');assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).jobId,null);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,1);});

const job901=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/job901-synthetic.json'),'utf8'));
test('synthetic job901 uses nested PeerFloodError over invite_membership_unconfirmed in stop cause',()=>{const api=harness().module._test,details=api.stopDetails({...job901,items:[job901.items[2],job901.items[0],job901.items[1]]});assert.equal(details.code,'PeerFloodError');assert.equal(details.reason,job901.items[2].diagnosis.verification_error.reason);assert.equal(details.nested,true);assert.equal(job901.counts.total,3);assert.equal(job901.counts.attempts,3);assert.equal(job901.counts.added,0);});
test('synthetic job901 renders protective stop cause and recipient-specific mutual/privacy outcomes with unchanged counts',async()=>{const x=harness(),api=x.module._test,c={...api.config(readyConfig(api),accounts,[target]),users:job901.items.map(i=>i.user_name)};x.context.job={...quickRecord(c),...job901,config:c,target,account:c.account,telegram_id:c.telegram_id,can_resume:true,account_attempts_today:3};x.context.location.search='?invite_job=901';await x.module.mount();const stop=x.el.innerHTML.match(/<strong>Причина остановки:<\/strong>([\s\S]*?)<\/p>/)?.[1];assert.match(stop,/PeerFloodError/);assert.match(stop,/Telegram ограничил действия аккаунта/);assert.ok(!stop.includes('требуется взаимный контакт'));assert.match(x.el.innerHTML,/@recipient_mutual[^<]*<span class="mic-item-reason">Telegram отклонил добавление этого получателя: требуется взаимный контакт с отправителем\./);assert.match(x.el.innerHTML,/UserNotMutualContactError/);assert.match(x.el.innerHTML,/настройки приватности получателя запрещают прямое добавление/);assert.match(x.el.innerHTML,/privacy_restricted/);assert.match(x.el.innerHTML,/Подтверждённых новых<\/dt><dd>0/);assert.match(x.el.innerHTML,/Попытки кампании<\/dt><dd>3 из/);assert.match(x.el.innerHTML,/Результаты по участникам \(3\)/);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});
test('unknown diagnostics have honest fallback and raw item error is never exposed',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.job={...quickRecord(c),state:'stopped',stop_reason:'unknown_stop',items:[{user_name:'valid_user',state:'uncertain',diagnosis:{},error:'session=PRIVATE_RAW_ERROR'}]};x.context.location.search='?invite_job=992';await x.module.mount();assert.match(x.el.innerHTML,/Причина остановки не уточнена в сохранённом результате/);assert.match(x.el.innerHTML,/Подробная причина не сохранена; проверьте журнал/);assert.ok(!x.el.innerHTML.includes('PRIVATE_RAW_ERROR'));});
test('diagnostic reason/code rendering escapes HTML and redacts credentials without serializing metadata',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.job={...quickRecord(c),state:'stopped',stop_reason:'invite_membership_unconfirmed',items:[{user_name:'valid_user',state:'uncertain',attempted_at:'2026-10-29T06:12:34Z',diagnosis:{code:'invite_membership_unconfirmed',verification_error:{code:'PeerFloodError',reason:'<img src=x onerror=alert(1)> password=TOP_SECRET bot_token=BOT_SECRET session_string=SESSION_SECRET api_hash=HASH_SECRET',rpc:{request:{secret:'METADATA_SECRET'}}}},error:'RAW_ERROR_SECRET'}]};x.context.location.search='?invite_job=992';await x.module.mount();assert.ok(x.el.innerHTML.includes('&lt;img'));assert.ok(!x.el.innerHTML.includes('<img src=x'));for(const secret of ['TOP_SECRET','BOT_SECRET','SESSION_SECRET','HASH_SECRET','METADATA_SECRET','RAW_ERROR_SECRET'])assert.ok(!x.el.innerHTML.includes(secret),secret);assert.match(x.el.innerHTML,/PeerFloodError/);assert.match(x.el.innerHTML,/\[скрыто\]/);const invalid=api.diagnosisDetails({state:'restricted',diagnosis:{code:'<script>alert(1)</script>',reason:'Текст причины'}});assert.equal(invalid.code,null);});
test('known manual pause reason stays authoritative and pending users do not acquire fabricated errors',()=>{const api=harness().module._test;assert.equal(api.stopDetails({...job901,state:'paused',stop_reason:'owner_pause'}).reason,'Пауза по вашей команде');assert.equal(api.diagnosisDetails({state:'pending',diagnosis:{}}),null);assert.equal(api.diagnosisDetails({state:'restricted',diagnosis:{code:'UserNotMutualContactError'}}).reason,'Telegram потребовал взаимный контакт для этого получателя.');});

test('recorded PeerFlood permits saving a draft but blocks explicit start without any start POST',async()=>{const x=harness();await fillQuick(x);x.context.fetchOverride=async(url,options)=>{if(url.endsWith('/quick-draft')){x.context.job={...quickRecord(JSON.parse(options.body).config),sender_error:'Telegram ограничил действия аккаунта (PeerFloodError).'};return response(x.context.job);}};await x.click('quick-draft');assert.match(x.el.innerHTML,/Кампания сохранена/);assert.match(x.el.innerHTML,/Исходящие остановлены: Telegram ограничил/);assert.match(x.el.innerHTML,/Сохранение кампании не приглашает людей и остаётся доступно/);await x.event('change','confirmed',true);assert.match(x.el.innerHTML,/data-mic="start" disabled/);await x.click('start');assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-draft')).length,1);assert.equal(x.calls.filter(c=>c.url.includes('/preview')).length,0);});
test('fresh sender_error null overrides stale cached account error for explicit start',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');accounts[0].error='PeerFloodError stale account cache';x.context.job={...x.context.job,sender_error:null};await x.click('status');await x.event('change','confirmed',true);assert.match(x.el.innerHTML,/data-mic="start">Запустить кампанию/);await x.click('start');assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,1);delete accounts[0].error;});
test('old job without sender_error falls back to saved account error; ordinary pause remains allowed',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');accounts[0].error='SessionRevokedError: сессия отозвана';await x.click('status');await x.event('change','confirmed',true);assert.match(x.el.innerHTML,/data-mic="start" disabled/);await x.click('start');assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);delete accounts[0].error;await x.click('status');await x.event('change','confirmed',true);assert.match(x.el.innerHTML,/data-mic="start">Запустить кампанию/);await x.click('start');assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,1);});
test('start rechecks cached job error immediately before write and catches newly protected sender',async()=>{const x=harness();await fillQuick(x);await x.click('quick-draft');await x.event('change','confirmed',true);x.context.job={...x.context.job,sender_error:'Telegram просит подождать (FloodWaitError).'};await x.click('start');assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')).length,0);assert.match(x.el.innerHTML,/FloodWaitError/);assert.equal(JSON.parse(x.memory.get('manual-invite-campaign-v1')).pendingWrite,'');});

test('saved PeerFlood banner separates connected session, historical refusal and unknown expiry without permitting start',async()=>{const x=harness();await fillQuick(x);x.context.fetchOverride=async(url,options)=>{if(url.endsWith('/quick-draft')){x.context.job={...quickRecord(JSON.parse(options.body).config),sender_error:'Telegram ограничил действия аккаунта. Задания остановлены; смена аккаунта автоматически не выполняется.'};return response(x.context.job);}};await x.click('quick-draft');await x.event('change','confirmed',true);assert.match(x.el.innerHTML,/Соединение в последнем ответе панели: <strong>подключено<\/strong>/);assert.match(x.el.innerHTML,/Это сохранённая причина остановки, а не новая проверка Telegram/);assert.match(x.el.innerHTML,/Время прежнего отказа аккаунта этим ответом не передано/);assert.match(x.el.innerHTML,/PeerFloodError срок окончания не указан/);assert.match(x.el.innerHTML,/Панель не знает, когда ограничение снимется/);assert.match(x.el.innerHTML,/Подключение не подтверждает разрешение приглашать участников/);assert.match(x.el.innerHTML,/data-mic="start" disabled/);assert.equal(x.calls.filter(c=>c.url.endsWith('/quick-start')||c.url.includes('/preview')).length,0);});
test('synthetic job901 stop time/code is labelled only as that campaign stop, never latest account failure',async()=>{const x=harness(),api=x.module._test,c={...api.config(readyConfig(api),accounts,[target]),users:job901.items.map(i=>i.user_name)};x.context.job={...quickRecord(c),...job901,config:c,target,account:c.account,telegram_id:c.telegram_id,sender_error:'PeerFloodError',can_resume:false};x.context.location.search='?invite_job=901';await x.module.mount();const stop=x.el.innerHTML.match(/<p class="cc-help" data-mic-recorded-stop>([\s\S]*?)<\/p>/)?.[1];assert.match(stop,/Последняя сохранённая остановка этой кампании №901/);assert.match(stop,/datetime="2020-01-01T00:00:00\.000000\+00:00"/);assert.match(stop,/PeerFloodError/);assert.match(stop,/а не время последней ошибки аккаунта/);assert.ok(!x.el.innerHTML.includes('Последняя ошибка аккаунта:'));assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});
test('revoked or disconnected account copy uses reported connection state and does not invent PeerFlood deadline',async()=>{const x=harness(),api=x.module._test,c=api.config(readyConfig(api),accounts,[target]);x.context.job={...quickRecord(c),sender_error:'SessionRevokedError: сессия отозвана'};x.context.location.search='?invite_job=992';x.context.fetchOverride=async url=>url==='/api/scanner/operations'?response({accounts:accounts.map(a=>({...a,connection:a.id==='primary'?'not_connected':a.connection})),jobs:[]}):undefined;await x.module.mount();assert.match(x.el.innerHTML,/Соединение в последнем ответе панели: <strong>не подключено<\/strong>/);assert.match(x.el.innerHTML,/сохранённая причина остановки/);assert.ok(!x.el.innerHTML.includes('PeerFloodError срок окончания'));assert.match(x.el.innerHTML,/data-mic="start" disabled/);assert.equal(x.calls.filter(c=>c.method==='POST').length,0);});
test('unknown campaign timestamp stays unknown and explanatory rendering issues no checks or controls',()=>{const x=harness(),api=x.module._test,before=x.calls.length;const html=api.recordedStopView({job_id:99,state:'stopped',stop_reason:'unknown_code',stopped_at:'not-a-date',items:[]});assert.match(html,/время остановки не передано/);assert.match(html,/№99/);assert.ok(!html.includes('Invalid Date'));assert.equal(x.calls.length,before);});
